Here's a recursive descent parser that handles `+ - * /` with correct precedence and parentheses:

```python
def calculate(expr: str) -> float:
    tokens = tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():          # handles + and -
        val = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():          # handles * and /
        val = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            rhs = parse_factor()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_factor():        # numbers, parens, unary minus
        tok = consume()
        if tok == '(':
            val = parse_expr()
            consume()          # ')'
            return val
        if tok == '-':
            return -parse_factor()
        return float(tok)

    return parse_expr()


def tokenize(expr: str):
    tokens, num = [], ''
    for ch in expr:
        if ch.isdigit() or ch == '.':
            num += ch
        else:
            if num:
                tokens.append(num)
                num = ''
            if ch in '+-*/()':
                tokens.append(ch)
            elif not ch.isspace():
                raise ValueError(f"Invalid character: {ch}")
    if num:
        tokens.append(num)
    return tokens


# Tests
print(calculate("3 + 5 * 2"))      # 13.0
print(calculate("(3 + 5) * 2"))    # 16.0
print(calculate("10 / 4 - 1"))     # 1.5
print(calculate("-3 + 2"))         # -1.0
```

**How it works:** the grammar enforces precedence — `expr` (lowest: `+ -`) calls `term` (`* /`), which calls `factor` (numbers/parens). Multiplication binds tighter because it's parsed deeper. Parentheses recurse back to `expr`.

