      .then(r => r.json())
      .then((data: Product[]) => {
        setResults(data);
        setLoading(false);
      })
      .catch(err => { if (err.name !== 'AbortError') setLoading(false); });
    return () => controller.abort();
  }, [debouncedQuery]);

  const grouped = useMemo(() => {
    return results.reduce<Record<string, Product[]>>((acc, p) => {
